var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Original behavior: decimalPlaces should default to 2 when not provided
    // Patched behavior: always uses options.decimalPlaces if options is truthy, even if decimalPlaces is undefined
    assert.strictEqual(bytes(1234, { decimalPlaces: undefined }), '1.23 KB');
    assert.strictEqual(bytes(1234, { decimalPlaces: 3 }), '1.234 KB');
    assert.strictEqual(bytes(1234, { decimalPlaces: undefined, unit: 'KB' }), '1.23 KB');
    assert.strictEqual(bytes(1234, { decimalPlaces: 3, unit: 'KB' }), '1.234 KB');
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original code checks typeof val === 'string' before calling parse.
    // The mutant skips this check and always checks val.length > 0.
    // This means that non-strings with a length property (like arrays) will be parsed.
    // Example: ms([1,2,3]) should throw an error but will not in the mutant.
    assert.throws(() => ms([1,2,3]), Error);
  });
});

