var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    assert.throws(() => ms(''), /val=\"\"/);
    assert.throws(() => ms(null), /val=null/);
    assert.throws(() => ms(undefined), /val=undefined/);
    assert.throws(() => ms([]), /val=\[\]/);
    assert.throws(() => ms({}), /val=\{\}/);
    assert.throws(() => ms(NaN), /val=NaN/);
    assert.throws(() => ms(Infinity), /val=Infinity/);
    assert.throws(() => ms(-Infinity), /val=-Infinity/);
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original code returns undefined for strings > 100 chars
    // The patched code always returns undefined due to if (false)
    // But we need to verify that the original behavior is actually observed
    // The test below checks that a very long string returns undefined
    // which is the expected behavior, but the patched version now breaks
    // this by skipping the length check entirely
    const longString = new Array(101).join('a');
    assert.strictEqual(ms(longString), undefined, 'Should return undefined for strings longer than 100 characters');
  });
});

